const DESCRIBED_KEY = 'users';
const DESCRIBED_TEXT = 'the user list';
const HOSTILE_DETAIL = '<img src=x onerror=alert(1)> {what}';

/** The status that has *kind*: the first of the status cases with it. */
function statusOf(kind: string): number {
  const found = STATUS_CASES.find((candidate) => candidate.kind === kind);
  if (found === undefined) {
    throw new Error(`No status case has the kind '${kind}'.`);
  }
  return found.status;
}

function problem(status: number, detail = 'why', retryAfter: number | null = null): ProblemDetails {
  return { type: 'about:blank', title: '', detail, status, errors: [], retryAfterMs: retryAfter };
}

/** A catalog that carries *carried* and words each with the key and arguments it was asked for. */
function catalog(carried: readonly string[]): ReadFailureMessages & { readonly asked: string[] } {
  const asked: string[] = [];
  return {
    asked,
    has: (messageKey) => carried.includes(messageKey) || messageKey === DESCRIBED_KEY,
    key: (messageKey, args = {}) => {
      if (messageKey === DESCRIBED_KEY) {
        return { text: DESCRIBED_TEXT };
      }
      asked.push(messageKey);
      return { text: `${messageKey}|${String(args['what'])}|${String(args['status'])}|${String(args['detail'])}` };
    },
  };
}

function site(scope: string, whatKey: string | null = null): ReadSite {
  return { scope, name: 'users', whatKey };
}

describe('read failures', () => {
  it('classifies every status the case table lists', () => {
    for (const { status, kind } of STATUS_CASES) {
      expect(readErrorKind(status), `status ${status}`).toBe(kind);
    }
  });

  it('reads a problem as a typed error', () => {
    for (const { status, kind } of STATUS_CASES) {
      expect(readErrorOf(problem(status, 'why'))).toEqual({ kind, status, detail: 'why', retryAfterMs: null });
    }
    expect(readErrorOf(problem(statusOf('rateLimited'), 'why', 30000)).retryAfterMs).toBe(30000);
  });

  it('reads the wait every Retry-After header the case table lists asks for', () => {
    for (const { header, expected } of RETRY_AFTER_CASES) {
      expect(retryAfterMs(header, RETRY_AFTER_NOW_MS), `Retry-After: ${String(header)}`).toBe(expected);
    }
  });

  it('caps a wait at a day and pauses a minute when none is asked for', () => {
    expect(RETRY_AFTER_CAP_MS).toBe(86400000);
    expect(RATE_LIMIT_PAUSE_MS).toBe(60000);
  });

  it('words a paused retry with the whole seconds left, never zero', () => {
    const asked: string[] = [];
    const counting: ReadFailureMessages = {
      has: () => false,
      key: (messageKey, args = {}) => {
        asked.push(`${messageKey} ${String(args['seconds'])}`);
        return { text: '' };
      },
    };
    retryInText(30000, counting);
    retryInText(1, counting);
    retryInText(29001, counting);
    expect(asked).toEqual(['framework.retryIn 30', 'framework.retryIn 1', 'framework.retryIn 30']);
  });

  it('takes the text from the first key the strings carry', () => {
    for (const { scope, kind, carried, expected } of TEXT_CASES) {
      const messages = catalog(carried);
      const text = readFailureText(problem(statusOf(kind)), messages, site(scope));
      if (expected === null) {
        expect(text, `${scope} ${kind} [${carried.join(', ')}]`).toBeNull();
      } else {
        expect(messages.asked, `${scope} ${kind} [${carried.join(', ')}]`).toEqual([expected]);
        expect(text).toBe(`${expected}|users|${statusOf(kind)}|why`);
      }
    }
  });

  it('names what was read by the message describedAs names', () => {
    const messages = catalog(['readFailed.other']);
    const text = readFailureText(problem(statusOf('forbidden')), messages, site('Overview.users', DESCRIBED_KEY));
    expect(text).toBe(`readFailed.other|${DESCRIBED_TEXT}|${statusOf('forbidden')}|why`);
  });

  it('hands the server detail over unchanged, to be shown as text', () => {
    const messages = catalog(['readFailed.other']);
    const text = readFailureText(problem(statusOf('server'), HOSTILE_DETAIL), messages, site('Overview.users'));
    expect(text).toBe(`readFailed.other|users|${statusOf('server')}|${HOSTILE_DETAIL}`);
  });

  it('words nothing for a read declared without a site', () => {
    expect(readFailureText(problem(statusOf('server')), catalog(['readFailed.other']), null)).toBeNull();
  });
});
